CREATE TRIGGER `notify_ride_cancelled` AFTER UPDATE OF `status` ON `rides` WHEN NEW.`status`='cancelled' AND OLD.`status`!='cancelled' BEGIN INSERT INTO `ride_notifications` (`recipient_id`, `event_type`, `actor_name`, `ride_id`) SELECT q.`rider_id`, 'ride_cancelled', NEW.`driver_name`, NEW.`id` FROM `requests` q WHERE q.`ride_id`=NEW.`id` AND q.`status` IN ('pending','accepted') AND NOT EXISTS (SELECT 1 FROM `user_blocks` b WHERE (b.`blocker_id`=NEW.`driver_id` AND b.`blocked_id`=q.`rider_id`) OR (b.`blocker_id`=q.`rider_id` AND b.`blocked_id`=NEW.`driver_id`)); END;
