CREATE TRIGGER `notify_request_cancelled` AFTER UPDATE OF `status` ON `requests` WHEN NEW.`status`='cancelled' AND OLD.`status` IN ('pending','accepted') BEGIN INSERT INTO `ride_notifications` (`recipient_id`, `event_type`, `actor_name`, `ride_id`) SELECT r.`driver_id`, 'request_cancelled', NEW.`rider_name`, NEW.`ride_id` FROM `rides` r WHERE r.`id`=NEW.`ride_id` AND NOT EXISTS (SELECT 1 FROM `user_blocks` b WHERE (b.`blocker_id`=r.`driver_id` AND b.`blocked_id`=NEW.`rider_id`) OR (b.`blocker_id`=NEW.`rider_id` AND b.`blocked_id`=r.`driver_id`)); END;
